function switchManagerTab(tabName, event) {
    if (event) event.preventDefault();
    document.querySelectorAll('.ffm-tab-pane').forEach(function(el) {
        el.style.display = (el.id === 'tab-' + tabName) ? 'block' : 'none';
    });
    document.querySelectorAll('#managerTabsNav .ffm-seg-tab').forEach(function(btn) {
        btn.classList.toggle('active', btn.getAttribute('data-tab') === tabName);
    });
    if (window.history && window.history.replaceState) {
        window.history.replaceState(null, '', '/ff/manager?tab=' + tabName);
    }
}

function switchActivitySub(subName, event) {
    if (event) event.preventDefault();
    document.querySelectorAll('.ffm-activity-sub').forEach(function(el) {
        el.style.display = (el.id === 'sub-' + subName) ? 'block' : 'none';
    });
    document.querySelectorAll('#activitySubNav .ffm-tab-pill').forEach(function(btn) {
        btn.classList.toggle('active', btn.getAttribute('data-sub') === subName);
    });
}

function toggleReportPeriod(mode) {
    var monthly = mode === 'monthly';
    document.getElementById('rf_date_wrap').style.display = monthly ? 'none' : '';
    document.getElementById('rf_period_wrap').style.display = monthly ? '' : 'none';
    document.getElementById('rf_date').disabled = monthly;
    document.getElementById('rf_period').disabled = !monthly;
}

document.addEventListener('DOMContentLoaded', function() {
    var params = new URLSearchParams(window.location.search);
    var sub = params.get('tab');
    if (sub === 'attendance' || sub === 'visits' || sub === 'expenses') {
        switchActivitySub(sub);
    }
    FFM.onPersonRoleChange && document.getElementById('pf_role') && FFM.onPersonRoleChange();
    var activeTab = document.querySelector('#managerTabsNav .ffm-seg-tab.active');
    if (activeTab && activeTab.scrollIntoView) {
        activeTab.scrollIntoView({inline: 'center', block: 'nearest'});
        window.scrollTo(0, 0);
    }
});
